import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class AK375 {
    public static Scanner scan = new Scanner(System.in);
    public String compute(int length, String str) {
        StringBuilder tempStr2 = new StringBuilder();
        StringBuilder tempStr1 = new StringBuilder();
        int maxLen = 0;
        int count = 0;

        for (int i = 0; i < length; i++) {
            char c = str.charAt(i);
            if (c == '(') {
                tempStr2.append('_');
                int j = i + 1;
                while (j < length && str.charAt(j) != ')') {
                    tempStr2.append(str.charAt(j));
                    j++;
                }
                i = j;
            } else if (c == ')') {
                tempStr1.append('_');
            } else {
                tempStr1.append(c);
            }
        }

        String[] parts2 = tempStr2.toString().split("_");
        List<String> list2 = new ArrayList<>();
        for (String part : parts2) {
            if (part != null && !part.isEmpty()) {
                list2.add(part);
            }
        }
        count = list2.size();

        String[] parts1 = tempStr1.toString().split("_");
        for (String p : parts1) {
            if (p.length() > maxLen) {
                maxLen = p.length();
            }
        }
        return maxLen + " " + count;
    }

    public static void main(String[] args) {
        while (scan.hasNext()) {
            int n = scan.nextInt();
            String s = scan.next();
            long startTime = System.currentTimeMillis();
            String result = new AK375().compute(n, s);
            long endTime = System.currentTimeMillis();
            System.out.println(result);
        }
    }
}
